207:   },
208:   methods: {
209:     breakdownGroup(key, index) {
210:       const bd = this.node(key).breakdowns
211:       if (!Array.isArray(bd)) return []
212:       const group = bd[index]
213:       return Array.isArray(group) ? group : []
214:     },
215:     shortLabel(v) {
216:       return v == null ? '' : String(v).replace(/[（(][^）)]*[）)]/g, '')
217:     },
218:     node(key) {
219:       const d = this.data || {}
220:       const raw = d[key]
221:       if (raw == null) return {}
222:       if (typeof raw === 'object') return raw
223:       return { value: raw }
224:     },
225:     value(key) {
226:       const v = this.node(key).value
227:       return v == null || v === '' ? '-' : v
228:     },
229:     label(key, fallback) {
230:       const l = this.node(key).label
231:       return l ? this.shortLabel(l) : fallback
232:     },
233:     unit(key, fallback) {
234:       const n = this.node(key)
235:       const u = n.unit == null ? fallback : n.unit
236:       return typeof u === 'string' ? u.replace(/[（）()]/g, '') : u
237:     },
238:     color(key) {
