248:       if (key) this.$emit('stat-click', key)
249:     },
250:     companyBreakdownNavKey(label) {
251:       const text = this.shortLabel(label).trim()
252:       if (text === '本地') return 'companyLocal'
253:       if (text === '非本地') return 'companyNonLocal'
254:       return null
255:     }
256:   }
