99: <script>
100: import SectionCard from './SectionCard.vue'
101: import SegTabs from './SegTabs.vue'
102: import HomeValueSkeleton from './HomeValueSkeleton.vue'
103: 
104: export default {
105:   name: 'SunshinePanel',
106:   components: { SectionCard, SegTabs, HomeValueSkeleton },
107:   props: {
108:     data: { type: Object, default: () => ({}) },
109:     loading: { type: Boolean, default: false }
110:   },
111:   data() {
112:     return {
113:       mode: 'month',
114:       segOptions: [
115:         { label: '历史累计', value: 'history' },
116:         { label: '当月数据', value: 'month' }
117:       ],
118:       bodyStyle: {
119:         padding: '14px 22px 12px',
120:         boxSizing: 'border-box',
121:         display: 'flex',
122:         flexDirection: 'column',
123:         position: 'relative'
124:       },
125:       drillLoading: false,
126:       drillVisible: false,
127:       drillRows: [],
128:       drillAreaName: '',
129:       drillAnchorStyle: null,
130:       drillCache: {},
131:       drillSwitchTimer: null,
132:       drillCloseTimer: null
133:     }
134:   },
135:   computed: {
136:     showCountColumns() {
137:       return this.data.showCountColumns !== false
138:     },
139:     dimensionIsComplex() {
140:       return this.data.rows && this.data.rows.length && this.data.rows[0].areaType === 'complex'
141:     },
142:     stats() {
143:       const s = this.data.stats || {}
144:       const pick = (v) => (v == null || v === '' ? '-' : v)
145:       return [
146:         { key: 'property', label: '物业服务', unit: '条', value: pick(s.property) },
147:         { key: 'benefit', label: '公共收益', unit: '条', value: pick(s.benefit) },
148:         { key: 'fund', label: '维修资金', unit: '条', value: pick(s.fund) }
149:       ]
150:     },
151:     rows() {
152:       const list = this.data.rows
153:       return (Array.isArray(list) ? list : []).slice(0, 7)
154:     },
155:     drillTitle() {
