163:       this.$emit('mode-change', val)
164:     }
165:   },
166:   methods: {
167:     pick(v) {
168:       return v == null ? '-' : v
169:     },
170:     clampPct(v) {
171:       const n = Number(v)
172:       if (Number.isNaN(n)) return 0
173:       return Math.max(0, Math.min(100, n))
174:     },
175:     formatRate(v) {
176:       if (v == null || v === '') return '-'
177:       const n = Number(v)
178:       if (Number.isNaN(n)) return String(v)
179:       return `${n % 1 === 0 ? n : n.toFixed(1)}%`
180:     },
181:     canDrill(row) {
182:       return !!row && row.areaType !== 'complex' && row.deptId != null
183:     },
184:     /** 悬停行政区划行时请求下钻数据；弹层锚点定位到鼠标所在行 */
185:     openDrill(row, evt) {
186:       if (!this.canDrill(row)) return
187:       if (this.drillCloseTimer) {
188:         clearTimeout(this.drillCloseTimer)
189:         this.drillCloseTimer = null
190:       }
191:       // 同一行重复悬停不重新处理
192:       if (this.drillAreaName === row.areaName && this.drillAnchorStyle) return
193:       // 同步捕获行位置：原生事件的 currentTarget 在事件处理后即被置空，不能留到延时回调里再取
194:       const anchorStyle = this.calcAnchorStyle(evt)
195:       // 轻微防抖，快速扫过整列时只在最终停留的行触发
196:       if (this.drillSwitchTimer) clearTimeout(this.drillSwitchTimer)
197:       this.drillSwitchTimer = setTimeout(() => {
198:         this.drillSwitchTimer = null
199:         this.doOpenDrill(row, anchorStyle)
200:       }, 120)
201:     },
202:     calcAnchorStyle(evt) {
203:       const rect = evt && evt.currentTarget ? evt.currentTarget.getBoundingClientRect() : null
204:       const cardRect = this.$el ? this.$el.getBoundingClientRect() : null
205:       if (!rect || !cardRect) return this.drillAnchorStyle
206:       return {
207:         left: `${rect.right - cardRect.left - 8}px`,
208:         top: `${rect.top - cardRect.top + rect.height / 2}px`
209:       }
210:     },
211:     cancelCloseDrill() {
212:       if (this.drillCloseTimer) {
213:         clearTimeout(this.drillCloseTimer)
214:         this.drillCloseTimer = null
215:       }
216:     },
217:     doOpenDrill(row, anchorStyle) {
218:       this.drillAreaName = row.areaName
