236:       this.drillCloseTimer = setTimeout(() => {
237:         this.drillCloseTimer = null
238:         this.closeDrill()
239:       }, 200)
240:     },
241:     closeDrill() {
242:       if (this.drillSwitchTimer) {
243:         clearTimeout(this.drillSwitchTimer)
244:         this.drillSwitchTimer = null
245:       }
246:       this.drillVisible = false
247:       this.drillLoading = false
248:       this.drillRows = []
249:       this.drillAreaName = ''
250:     },
251:     setDrillRows(rows) {
