.home-v2__row--3 {
  grid-template-columns: 1fr;
  grid-auto-rows: auto;
}

/* 响应式：默认 3 列仅在宽屏生效；中屏降为 2 列（首卡整行铺满，后两张并排）；窄屏单列自适应高度 */
@media (max-width: 1199px) {
  .home-v2__row--1,
  .home-v2__row--2 {
    grid-template-columns: 1fr 1fr;
    grid-auto-rows: 380px;
  }

  /* 首卡（关键数据导航 / 公共收益）整行，后两张并排，避免 3 项在 2 列下出现孤儿格 */
  .home-v2__row--1 > :first-child,
  .home-v2__row--2 > :first-child {
    grid-column: 1 / -1;
  }
}

@media (max-width: 767px) {
  .home-v2 {
    padding: 12px;
  }

  /* 区域选择栏换行：tab 整行在上，统计周期整行在下，避免挤压重叠 */
  .home-v2__region {
    flex-wrap: wrap;
    padding: 12px 14px;
    gap: 10px;
  }

  .home-v2__region-tabs {
    flex: 1 1 100%;
    order: -1;
